customMethods.script:

	if not text: return ''

	json = system.util.jsonDecode(text)

	output = []

	def runData(name, data, lv=0, c=False):
		padding = '  ' * lv
		name = '' if name is None else '"{}": '.format(name)
		c = ',' if c else ''

		if type(data) == dict:
			if len(data) == 0: output.append(padding + name + '{}' + c)
			else:
				l = len(data) - 1
				output.append(padding + name + '{')
				for i, item in enumerate(data.items()):
					k, v = item
					runData(k, v, lv+1, i != l)
				output.append(padding + '}' + c)

		elif type(data) == list:
			if len(data) == 0: output.append(padding + name + '[]' + c)
			else:
				l = len(data) - 1
				output.append(padding + name + '[')
				for i, v in enumerate(data):
					runData(None, v, lv+1, i != l)
				output.append(padding + ']' + c)

		elif data == None:
			output.append(padding + name + 'null' + c)

		elif type(data) == str:
			if data[0] == '"': data = data[1:]
			if data[-1] == '"': data = data[:-1]
			output.append(padding + name + '"' + data + '"' + c)

		elif type(data) == bool:
			output.append(padding + name + str(data).lower() + c)

		else:
			output.append(padding + name + str(data) + c)

	runData(None, json)

	return '''
'''.join(output)
